import{_ as r,C as a,c as s,o as n,a3 as t,G as i}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Aged receivable and aged payable","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/reporting/aged-receivable-and-payable.md","filePath":"master/finance/reporting/aged-receivable-and-payable.md","lastUpdated":1791902625000}'),l={name:"master/finance/reporting/aged-receivable-and-payable.md"};function d(g,e,h,p,c,u){const o=a("ImagePopup");return n(),s("div",null,[e[0]||(e[0]=t('<h1 id="aged-receivable-and-aged-payable" tabindex="-1">Aged receivable and aged payable <a class="header-anchor" href="#aged-receivable-and-aged-payable" aria-label="Permalink to &quot;Aged receivable and aged payable&quot;">​</a></h1><p>These two reports show the open amounts by age. <strong>Aged Receivable</strong> lists what customers still owe you. <strong>Aged Payable</strong> lists what you still owe vendors. Use them to chase late payers and to plan which bills to pay first.</p><blockquote><p><strong>In simple words:</strong> Open invoices sorted by how late they are. The older the amount, the more urgent it is.</p></blockquote><p>They are in the Accounting app only:</p><ul><li><code>Accounting → Reporting → Aged Receivable</code></li><li><code>Accounting → Reporting → Aged Payable</code></li></ul><p>Both reports work the same way. Only the accounts differ: receivable for customers, payable for vendors.</p><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2>',7)),i(o,{src:"/images1/finance/aged_receivable.png",alt:"Aged Receivable As of 10/12/2026 with Based on Due Date, Period Length 30 Days, showing Azure Interiors 1,207.50"}),e[1]||(e[1]=t('<ul><li><strong><em>As of:</em></strong> The date of the report. It starts as today.</li><li><strong><em>Based on:</em></strong> <strong>Due Date</strong> or <strong>Invoice Date</strong>. It decides which date Aureus uses to measure the age.</li><li><strong><em>Period Length (days):</em></strong> <strong>30 Days</strong>, <strong>60 Days</strong> or <strong>90 Days</strong>. It is the width of each column.</li><li><strong><em>Journals:</em></strong> Limit the report to chosen journals.</li><li><strong><em>Partners:</em></strong> Limit the report to chosen partners.</li><li><strong><em>Entries:</em></strong> <strong>Posted Entries</strong> (default) or <strong>All Entries</strong>. The second one includes drafts.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A yellow message &quot;There are unposted Journal Entries prior or included in this period.&quot; means some entries are still drafts. The report shows posted entries only, so confirm them or choose <strong>All Entries</strong>.</p></div><h2 id="how-to-read-it" tabindex="-1">How to read it <a class="header-anchor" href="#how-to-read-it" aria-label="Permalink to &quot;How to read it&quot;">​</a></h2><p>The columns are <strong>Aged Receivable</strong> (the partner), <strong>Invoice Date</strong>, <strong>At Date</strong>, <strong>1-30</strong>, <strong>31-60</strong>, <strong>61-90</strong>, <strong>91-120</strong>, <strong>Older</strong> and <strong>Total</strong>. The numbers shown depend on the period length.</p><ul><li><strong>At Date:</strong> Not late yet. The due date is after the <strong>As of</strong> date.</li><li><strong>1-30:</strong> Late by 1 to 30 days (with a 30 day period).</li><li><strong>31-60</strong>, <strong>61-90</strong>, <strong>91-120:</strong> Later buckets.</li><li><strong>Older:</strong> Later than four periods.</li><li><strong>Total:</strong> All open amounts of the partner.</li></ul><p>Click a partner row or use <strong>Expand All</strong> to see each open invoice. <strong>Collapse All</strong> closes the rows. The last row, <strong>Total Aged Receivable</strong>, sums each column.</p><p>Example. As of Oct 12, 2026 the report shows one partner.</p><table tabindex="0"><thead><tr><th>Partner</th><th>At Date</th><th>Total</th></tr></thead><tbody><tr><td>Azure Interiors</td><td>1,207.50</td><td>1,207.50</td></tr></tbody></table><p>Invoice INV/2026/1 has no due date, so Aureus counts it as not late. The amount sits in <strong>At Date</strong>. If it had a due date of Sep 1, 2026, it would sit in <strong>31-60</strong>.</p><p>Aged Payable on the same date shows the message &quot;No receivables found for the selected criteria.&quot; The only bill is paid.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Click <strong>Export Excel</strong> or <strong>Export PDF</strong>. Expand the partners first. The export includes the invoice lines of the partners you opened.</p><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>What is the difference between Due Date and Invoice Date?</strong><strong>Due Date</strong> measures lateness. <strong>Invoice Date</strong> measures how old the invoice is.</p><p><strong>Why is a paid invoice missing?</strong> Only open amounts are listed.</p><p><strong>Why do the numbers differ from the Partner Ledger?</strong> The aged reports list open amounts only. The partner ledger shows all movements.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./partner-ledger.html">Partner ledger</a></li><li><a href="./../payments/register-payment.html">Register a payment</a></li><li><a href="./../customer-invoices/payment-terms.html">Payment terms</a></li></ul>',18))])}const f=r(l,[["render",d]]);export{b as __pageData,f as default};
